public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);

    List recIdList = strSplit(_value, ',');
    ListEnumerator enumerator = recIdList.getEnumerator();
    while (enumerator.moveNext())
    {
        int64 value = any2Int64(enumerator.current());
        EcoResCategory ecoResCategory = EcoResCategory::find(value);
        qbds.addRange(fieldNum(EcoResCategory, NestedSetLeft)).value(SysQuery::range(ecoResCategory.NestedSetLeft, ecoResCategory.NestedSetRight));
        qbds.addRange(fieldNum(EcoResCategory, NestedSetRight)).value(SysQuery::range(ecoResCategory.NestedSetLeft, ecoResCategory.NestedSetRight));
        qbds.addRange(fieldNum(EcoResCategory, CategoryHierarchy)).value(int642Str(ecoResCategory.CategoryHierarchy));
    }

    return _query;
}
